using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
internal static class StudioUi{
 internal static readonly Color Ink=Color.FromArgb(31,42,48),Muted=Color.FromArgb(104,116,123),Paper=Color.FromArgb(245,247,248),Line=Color.FromArgb(220,226,229),Accent=Color.FromArgb(18,112,100),Rail=Color.FromArgb(29,40,46);
 internal static void Apply(Control root){foreach(Control c in root.Controls){if(c is Button){var b=(Button)c;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Line;b.FlatAppearance.MouseOverBackColor=Color.FromArgb(230,240,237);if(b.BackColor==SystemColors.Control||b.BackColor==Color.White)b.BackColor=Color.FromArgb(251,252,252);b.ForeColor=Ink;b.Cursor=Cursors.Hand;b.Font=new Font("Microsoft YaHei UI",9.5f);}else if(c is TextBox){((TextBox)c).BorderStyle=BorderStyle.FixedSingle;c.ForeColor=Ink;}else if(c is ComboBox){((ComboBox)c).FlatStyle=FlatStyle.Flat;c.BackColor=Paper;c.ForeColor=Ink;}Apply(c);}}
 internal static Button Button(string text,Rectangle r,bool primary=false){var b=new Button{Text=text,Bounds=r,FlatStyle=FlatStyle.Flat,BackColor=primary?Accent:Color.FromArgb(251,252,252),ForeColor=primary?Color.White:Ink,Cursor=Cursors.Hand};b.FlatAppearance.BorderColor=primary?Accent:Line;return b;}
 internal static Label Label(string text,Rectangle r,float size=10,bool bold=false){return new Label{Text=text,Bounds=r,ForeColor=Ink,Font=new Font("Microsoft YaHei UI",size,bold?FontStyle.Bold:FontStyle.Regular)};}
 internal static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
internal sealed class ColorTile:Button{
 internal Color Swatch;internal string Caption,Detail;internal bool Selected;
 internal ColorTile(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Cursor=Cursors.Hand;FlatStyle=FlatStyle.Flat;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?StudioUi.Paper:Parent.BackColor);using(var path=StudioUi.Round(new RectangleF(1,1,Width-3,Height-3),7))using(var bg=new SolidBrush(Color.FromArgb(252,253,253)))using(var pen=new Pen(Selected?StudioUi.Accent:StudioUi.Line,Selected?2:1)){g.FillPath(bg,path);g.DrawPath(pen,path);}using(var path=StudioUi.Round(new RectangleF(8,8,Width-16,25),4))using(var b=new SolidBrush(Swatch))g.FillPath(b,path);TextRenderer.DrawText(g,Caption??"",Font,new Rectangle(8,37,Width-16,19),StudioUi.Ink,TextFormatFlags.EndEllipsis);using(var f=new Font(Font.FontFamily,8))TextRenderer.DrawText(g,Detail??"",f,new Rectangle(8,57,Width-16,16),StudioUi.Muted,TextFormatFlags.EndEllipsis);}
}
